Here is the commit message:
btrfs: fix invalid leaf access in btrfs_quota_enable() if ref
 key not found

If btrfs_search_slot_for_read() returns 1, it means we did not find any
key greater than or equals to the key we asked for, meaning we have
reached the end of the tree and therefore the path is not valid. If
this happens we need to break out of the loop and stop, instead of
continuing and accessing an invalid path.

Fixes: 5223cc60b40a ("btrfs: drop the path before adding qgroup items when enabling qgroups")
Reviewed-by: Qu Wenruo <wqu@suse.com>
Signed-off-by: Filipe Manana <fdmanana@suse.com>
Reviewed-by: David Sterba <dsterba@suse.com>
Signed-off-by: David Sterba <dsterba@suse.com>

Here is the root cause:
The bug occurs in `btrfs_quota_enable()` when `btrfs_search_slot_for_read()` returns 1, indicating no key greater than or equal to the requested key exists (end of tree reached). In this case, the path becomes invalid, but the original code used `continue` to proceed with the loop. This would subsequently attempt to access the invalid path (e.g., calling `btrfs_next_item` on an invalid path), leading to an invalid leaf access and potential crash.

Here is the patch:

 int btrfs_quota_enable(struct btrfs_fs_info *fs_info,
 		       struct btrfs_ioctl_quota_ctl_args *quota_ctl_args)
 {
 	struct btrfs_root *quota_root;
 	struct btrfs_root *tree_root = fs_info->tree_root;
 	struct btrfs_path *path = NULL;
 	struct btrfs_qgroup_status_item *ptr;
 	struct extent_buffer *leaf;
 	struct btrfs_key key;
 	struct btrfs_key found_key;
 	struct btrfs_qgroup *qgroup = NULL;
 	struct btrfs_qgroup *prealloc = NULL;
 	struct btrfs_trans_handle *trans = NULL;
 	const bool simple = (quota_ctl_args->cmd == BTRFS_QUOTA_CTL_ENABLE_SIMPLE_QUOTA);
 	int ret = 0;
 	int slot;

 	/*
 	 * We need to have subvol_sem write locked, to prevent races between
 	 * concurrent tasks trying to enable quotas, because we will unlock
 	 * and relock qgroup_ioctl_lock before setting fs_info->quota_root
 	 * and before setting BTRFS_FS_QUOTA_ENABLED.
 	 */
 	lockdep_assert_held_write(&fs_info->subvol_sem);

 	if (btrfs_fs_incompat(fs_info, EXTENT_TREE_V2)) {
 		btrfs_err(fs_info,
 			  "qgroups are currently unsupported in extent tree v2");
 		return -EINVAL;
 	}

 	mutex_lock(&fs_info->qgroup_ioctl_lock);
 	if (fs_info->quota_root)
 		goto out;

 	ret = btrfs_sysfs_add_qgroups(fs_info);
 	if (ret < 0)
 		goto out;

 	/*
 	 * Unlock qgroup_ioctl_lock before starting the transaction. This is to
 	 * avoid lock acquisition inversion problems (reported by lockdep) between
 	 * qgroup_ioctl_lock and the vfs freeze semaphores, acquired when we
 	 * start a transaction.
 	 * After we started the transaction lock qgroup_ioctl_lock again and
 	 * check if someone else created the quota root in the meanwhile. If so,
 	 * just return success and release the transaction handle.
 	 *
 	 * Also we don't need to worry about someone else calling
 	 * btrfs_sysfs_add_qgroups() after we unlock and getting an error because
 	 * that function returns 0 (success) when the sysfs entries already exist.
 	 */
 	mutex_unlock(&fs_info->qgroup_ioctl_lock);

 	/*
 	 * 1 for quota root item
 	 * 1 for BTRFS_QGROUP_STATUS item
 	 *
 	 * Yet we also need 2*n items for a QGROUP_INFO/QGROUP_LIMIT items
 	 * per subvolume. However those are not currently reserved since it
 	 * would be a lot of overkill.
 	 */
 	trans = btrfs_start_transaction(tree_root, 2);

 	mutex_lock(&fs_info->qgroup_ioctl_lock);
 	if (IS_ERR(trans)) {
 		ret = PTR_ERR(trans);
 		trans = NULL;
 		goto out;
 	}

 	if (fs_info->quota_root)
 		goto out;

 	/*
 	 * initially create the quota tree
 	 */
 	quota_root = btrfs_create_tree(trans, BTRFS_QUOTA_TREE_OBJECTID);
 	if (IS_ERR(quota_root)) {
 		ret =  PTR_ERR(quota_root);
 		btrfs_abort_transaction(trans, ret);
 		goto out;
 	}

 	path = btrfs_alloc_path();
 	if (unlikely(!path)) {
 		ret = -ENOMEM;
 		btrfs_abort_transaction(trans, ret);
 		goto out_free_root;
 	}

 	key.objectid = 0;
 	key.type = BTRFS_QGROUP_STATUS_KEY;
 	key.offset = 0;

 	ret = btrfs_insert_empty_item(trans, quota_root, path, &key,
 				      sizeof(*ptr));
 	if (unlikely(ret)) {
 		btrfs_abort_transaction(trans, ret);
 		goto out_free_path;
 	}

 	leaf = path->nodes[0];
 	ptr = btrfs_item_ptr(leaf, path->slots[0],
 				 struct btrfs_qgroup_status_item);
 	btrfs_set_qgroup_status_generation(leaf, ptr, trans->transid);
 	btrfs_set_qgroup_status_version(leaf, ptr, BTRFS_QGROUP_STATUS_VERSION);
 	fs_info->qgroup_flags = BTRFS_QGROUP_STATUS_FLAG_ON;
 	if (simple) {
 		fs_info->qgroup_flags |= BTRFS_QGROUP_STATUS_FLAG_SIMPLE_MODE;
 		btrfs_set_fs_incompat(fs_info, SIMPLE_QUOTA);
 		btrfs_set_qgroup_status_enable_gen(leaf, ptr, trans->transid);
 	} else {
 		fs_info->qgroup_flags |= BTRFS_QGROUP_STATUS_FLAG_INCONSISTENT;
 	}
 	btrfs_set_qgroup_status_flags(leaf, ptr, fs_info->qgroup_flags &
 				      BTRFS_QGROUP_STATUS_FLAGS_MASK);
 	btrfs_set_qgroup_status_rescan(leaf, ptr, 0);

 	key.objectid = 0;
 	key.type = BTRFS_ROOT_REF_KEY;
 	key.offset = 0;

 	btrfs_release_path(path);
 	ret = btrfs_search_slot_for_read(tree_root, &key, path, 1, 0);
 	if (ret > 0)
 		goto out_add_root;
 	if (unlikely(ret < 0)) {
 		btrfs_abort_transaction(trans, ret);
 		goto out_free_path;
 	}

 	while (1) {
 		slot = path->slots[0];
 		leaf = path->nodes[0];
 		btrfs_item_key_to_cpu(leaf, &found_key, slot);

 		if (found_key.type == BTRFS_ROOT_REF_KEY) {

 			/* Release locks on tree_root before we access quota_root */
 			btrfs_release_path(path);

 			/* We should not have a stray @prealloc pointer. */
 			ASSERT(prealloc == NULL);
 			prealloc = kzalloc(sizeof(*prealloc), GFP_NOFS);
 			if (unlikely(!prealloc)) {
 				ret = -ENOMEM;
 				btrfs_abort_transaction(trans, ret);
 				goto out_free_path;
 			}

 			ret = add_qgroup_item(trans, quota_root,
 					      found_key.offset);
 			if (unlikely(ret)) {
 				btrfs_abort_transaction(trans, ret);
 				goto out_free_path;
 			}

 			qgroup = add_qgroup_rb(fs_info, prealloc, found_key.offset);
 			prealloc = NULL;
 			ret = btrfs_sysfs_add_one_qgroup(fs_info, qgroup);
 			if (unlikely(ret < 0)) {
 				btrfs_abort_transaction(trans, ret);
 				goto out_free_path;
 			}
 			ret = btrfs_search_slot_for_read(tree_root, &found_key,
 							 path, 1, 0);
 			if (unlikely(ret < 0)) {
 				btrfs_abort_transaction(trans, ret);
 				goto out_free_path;
 			}
 			if (ret > 0) {
 				/*
-				 * Shouldn't happen, but in case it does we
-				 * don't need to do the btrfs_next_item, just
-				 * continue.
+				 * Shouldn't happen because the key should still
+				 * be there (return 0), but in case it does it
+				 * means we have reached the end of the tree -
+				 * there are no more leaves with items that have
+				 * a key greater than or equals to @found_key,
+				 * so just stop the search loop.
 				 */
-				continue;
+				break;
 			}
 		}
 		ret = btrfs_next_item(tree_root, path);
 		if (unlikely(ret < 0)) {
 			btrfs_abort_transaction(trans, ret);
 			goto out_free_path;
 		}
 		if (ret)
 			break;
 	}

 out_add_root:
 	btrfs_release_path(path);
 	ret = add_qgroup_item(trans, quota_root, BTRFS_FS_TREE_OBJECTID);
 	if (unlikely(ret)) {
 		btrfs_abort_transaction(trans, ret);
 		goto out_free_path;
 	}

 	ASSERT(prealloc == NULL);
 	prealloc = kzalloc(sizeof(*prealloc), GFP_NOFS);
 	if (!prealloc) {
 		ret = -ENOMEM;
 		goto out_free_path;
 	}
 	qgroup = add_qgroup_rb(fs_info, prealloc, BTRFS_FS_TREE_OBJECTID);
 	prealloc = NULL;
 	ret = btrfs_sysfs_add_one_qgroup(fs_info, qgroup);
 	if (unlikely(ret < 0)) {
 		btrfs_abort_transaction(trans, ret);
 		goto out_free_path;
 	}

 	fs_info->qgroup_enable_gen = trans->transid;

 	mutex_unlock(&fs_info->qgroup_ioctl_lock);
 	/*
 	 * Commit the transaction while not holding qgroup_ioctl_lock, to avoid
 	 * a deadlock with tasks concurrently doing other qgroup operations, such
 	 * adding/removing qgroups or adding/deleting qgroup relations for example,
 	 * because all qgroup operations first start or join a transaction and then
 	 * lock the qgroup_ioctl_lock mutex.
 	 * We are safe from a concurrent task trying to enable quotas, by calling
 	 * this function, since we are serialized by fs_info->subvol_sem.
 	 */
 	ret = btrfs_commit_transaction(trans);
 	trans = NULL;
 	mutex_lock(&fs_info->qgroup_ioctl_lock);
 	if (ret)
 		goto out_free_path;

 	/*
 	 * Set quota enabled flag after committing the transaction, to avoid
 	 * deadlocks on fs_info->qgroup_ioctl_lock with concurrent snapshot
 	 * creation.
 	 */
 	spin_lock(&fs_info->qgroup_lock);
 	fs_info->quota_root = quota_root;
 	set_bit(BTRFS_FS_QUOTA_ENABLED, &fs_info->flags);
 	spin_unlock(&fs_info->qgroup_lock);

 	/* Skip rescan for simple qgroups. */
 	if (btrfs_qgroup_mode(fs_info) == BTRFS_QGROUP_MODE_SIMPLE)
 		goto out_free_path;

 	ret = qgroup_rescan_init(fs_info, 0, 1);
 	if (!ret) {
 	        qgroup_rescan_zero_tracking(fs_info);
 		fs_info->qgroup_rescan_running = true;
 	        btrfs_queue_work(fs_info->qgroup_rescan_workers,
 	                         &fs_info->qgroup_rescan_work);
 	} else {
 		/*
 		 * We have set both BTRFS_FS_QUOTA_ENABLED and
 		 * BTRFS_QGROUP_STATUS_FLAG_ON, so we can only fail with
 		 * -EINPROGRESS. That can happen because someone started the
 		 * rescan worker by calling quota rescan ioctl before we
 		 * attempted to initialize the rescan worker. Failure due to
 		 * quotas disabled in the meanwhile is not possible, because
 		 * we are holding a write lock on fs_info->subvol_sem, which
 		 * is also acquired when disabling quotas.
 		 * Ignore such error, and any other error would need to undo
 		 * everything we did in the transaction we just committed.
 		 */
 		ASSERT(ret == -EINPROGRESS);
 		ret = 0;
 	}

 out_free_path:
 	btrfs_free_path(path);
 out_free_root:
 	if (ret)
 		btrfs_put_root(quota_root);
 out:
 	if (ret)
 		btrfs_sysfs_del_qgroups(fs_info);
 	mutex_unlock(&fs_info->qgroup_ioctl_lock);
 	if (ret && trans)
 		btrfs_end_transaction(trans);
 	else if (trans)
 		ret = btrfs_end_transaction(trans);
 	kfree(prealloc);
 	return ret;
 }



